using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// Set up options with a known type resolver (source-gen context)
var options = new JsonSerializerOptions
{
    TypeInfoResolver = MyContext.Default
};

// 1) Strongly-typed retrieval: GetTypeInfo<T>() returns JsonTypeInfo<T> directly
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"Got typed metadata for: {personInfo.Type.Name}");

// 2) Probe without throwing: TryGetTypeInfo returns false if metadata isn't available
if (options.TryGetTypeInfo(typeof(UnknownRecord), out JsonTypeInfo? info))
{
    Console.WriteLine($"Found metadata for UnknownRecord: {info!.Type.Name}");
}
else
{
    Console.WriteLine("No metadata for UnknownRecord — no exception thrown.");
}

